import React, { useState } from 'react';
import { Button, Dialog, DialogHeader, DialogTitle, DialogBody, DialogFooter, Text } from '@jinx-ui/react';

interface DeleteProjectButtonProps {
  onConfirm: () => void;
}

const DeleteProjectButton: React.FC<DeleteProjectButtonProps> = ({ onConfirm }) => {
  const [isOpen, setIsOpen] = useState(false);

  const handleOpen = () => setIsOpen(true);
  const handleClose = () => setIsOpen(false);

  const handleConfirm = () => {
    onConfirm();
    setIsOpen(false);
  };

  return (
    <>
      <Button variant="danger" onClick={handleOpen}>
        Удалить проект
      </Button>

      <Dialog open={isOpen} onClose={handleClose}>
        <DialogHeader>
          <DialogTitle>Удалить проект?</DialogTitle>
        </DialogHeader>
        <DialogBody>
          <Text className="jx-text-secondary">
            Это действие необратимо. Все данные проекта будут удалены безвозвратно.
          </Text>
        </DialogBody>
        <DialogFooter>
          <Button variant="secondary" onClick={handleClose}>
            Отмена
          </Button>
          <Button variant="danger" onClick={handleConfirm}>
            Удалить
          </Button>
        </DialogFooter>
      </Dialog>
    </>
  );
};

export default DeleteProjectButton;

